<script setup>
import { computed, ref } from 'vue'
const props=defineProps({fsmState:{type:String,default:null},performance:{type:Object,default:null},dailyReport:{type:Object,default:null},activeShiftId:{type:String,default:null},odometer:{type:Number,default:null},lastAuthoritativeOdometer:{type:Number,default:null},commands:{type:Object,required:true},captureEnabled:{type:Boolean,default:true}})
const emit=defineEmits(['refresh'])
const section=ref(props.captureEnabled?'capture':'summary'),expandedForm=ref(null),busy=ref(false),message=ref(''),error=ref(''),odometerReading=ref(''),revenue=ref(''),expenseAmount=ref(''),expenseCategory=ref(''),expenseDescription=ref(''),fuelAmount=ref(''),fuelPrice=ref(''),maintenanceAmount=ref(''),maintenanceCategory=ref(''),maintenanceDescription=ref(''),maintenanceReference=ref(''),maintenanceLife=ref(''),maintenanceOdometer=ref('')
const money=v=>v==null?'—':`₹${(Number(v)/100).toFixed(2)}`,number=v=>v==null?'—':Number(v).toFixed(1),effectiveOdometer=computed(()=>Number.isFinite(props.odometer)?props.odometer:null),authoritativeOdometerLocked=computed(()=>effectiveOdometer.value!==null),report=computed(()=>props.dailyReport||{}),history=computed(()=>Array.isArray(props.performance?.history)?props.performance.history:[]),revenueEnabled=computed(()=>props.fsmState!=='SHIFT_WAITING'),contextualOdometerEnabled=computed(()=>props.fsmState!=='SHIFT_WAITING'),odometerRegression=computed(()=>{const value=Number(odometerReading.value);const previous=props.lastAuthoritativeOdometer;return Number.isFinite(value)&&Number.isFinite(previous)&&value<previous}),odometerWarning=computed(()=>odometerRegression.value?`Odometer reading cannot be lower than previous reading (${props.lastAuthoritativeOdometer} km)`:''),odometerSubmitDisabled=computed(()=>busy.value||odometerRegression.value)
function resetNotice(){message.value='';error.value=''}
function validPositive(v){return Number.isFinite(Number(v))&&Number(v)>0}
function toggleForm(name){expandedForm.value=expandedForm.value===name?null:name}
async function run(label,action){resetNotice();busy.value=true;try{await action();message.value=`${label} recorded.`;emit('refresh')}catch(err){error.value=String(err?.message||err)}finally{busy.value=false}}
async function saveOdometer(){await run('Odometer',async()=>{if(!contextualOdometerEnabled.value)throw new Error('Odometer capture is available after shift start');if(!Number.isInteger(Number(odometerReading.value))||Number(odometerReading.value)<0)throw new Error('Odometer must be a non-negative whole number');if(odometerRegression.value)throw new Error(odometerWarning.value);await props.commands.recordOdometer({odometer:Number(odometerReading.value),source:'MANUAL'});odometerReading.value='';expandedForm.value=null})}
async function saveRevenue(){await run('Revenue',async()=>{if(!revenueEnabled.value)throw new Error('Revenue capture is available after shift start');if(!validPositive(revenue.value))throw new Error('Revenue must be positive');await props.commands.recordRevenue({amount_paise:Math.round(Number(revenue.value)*100),scope:'BUSINESS',business_date:new Date().toISOString().slice(0,10),work_session_id:props.activeShiftId||null});revenue.value='';expandedForm.value=null})}
async function saveExpense(){await run('Expense',async()=>{if(!validPositive(expenseAmount.value))throw new Error('Expense amount must be positive');if(!expenseCategory.value.trim())throw new Error('Expense category is required');await props.commands.recordExpense({amount:Number(expenseAmount.value),category:expenseCategory.value.trim(),description:expenseDescription.value.trim(),date:new Date().toISOString().slice(0,10),work_session_id:props.activeShiftId||null});expenseAmount.value='';expenseCategory.value='';expenseDescription.value='';expandedForm.value=null})}
async function saveFuel(){await run('Fuel',async()=>{if(!validPositive(fuelAmount.value)||!validPositive(fuelPrice.value))throw new Error('Fuel amount and price must be positive');if(effectiveOdometer.value==null)throw new Error('Authoritative odometer is unavailable');await props.commands.recordFuel({amount_paise:Math.round(Number(fuelAmount.value)*100),price_per_kg:Number(fuelPrice.value),odometer:Math.round(effectiveOdometer.value),scope:'BUSINESS',date:new Date().toISOString().slice(0,10)});fuelAmount.value='';fuelPrice.value='';expandedForm.value=null})}
async function saveMaintenance(){await run('Maintenance',async()=>{if(!validPositive(maintenanceAmount.value))throw new Error('Maintenance amount must be positive');if(!maintenanceCategory.value.trim())throw new Error('Maintenance category is required');const odometer=maintenanceOdometer.value===''?effectiveOdometer.value:Number(maintenanceOdometer.value);if(!Number.isFinite(odometer)||odometer<0)throw new Error('Maintenance odometer is required');const expectedKmLife=maintenanceLife.value===''?null:Number(maintenanceLife.value);if(expectedKmLife!=null&&(!Number.isInteger(expectedKmLife)||expectedKmLife<=0))throw new Error('KM life must be a positive whole number');await props.commands.recordMaintenance({maintenanceId:crypto.randomUUID(),amount:Number(maintenanceAmount.value),category:maintenanceCategory.value.trim(),description:maintenanceDescription.value.trim(),reference:maintenanceReference.value.trim()||null,date:new Date().toISOString().slice(0,10),odometer:Math.round(odometer),vehicle:'CURRENT_VEHICLE',expectedKmLife,workSessionId:props.activeShiftId||null});maintenanceAmount.value='';maintenanceCategory.value='';maintenanceDescription.value='';maintenanceReference.value='';maintenanceLife.value='';maintenanceOdometer.value='';expandedForm.value=null})}
</script>
<template><section class="work-operations" aria-label="Work operations"><header class="operations-header"><div><span class="eyebrow">WORK OPERATIONS</span><h2>Record activity</h2></div><span v-if="busy" class="state">Saving…</span></header><div class="tabs" role="tablist" aria-label="Work operation views"><button v-if="captureEnabled" type="button" :class="{active:section==='capture'}" @click="section='capture'">Capture</button><button type="button" :class="{active:section==='summary'}" @click="section='summary'">Today</button><button type="button" :class="{active:section==='history'}" @click="section='history'">History</button></div><p v-if="message" class="notice success" role="status">{{message}}</p><p v-if="error" class="notice error" role="alert">{{error}}</p><template v-if="section==='capture'&&captureEnabled"><div class="forms"><form v-if="!authoritativeOdometerLocked&&contextualOdometerEnabled" class="accordion" novalidate @submit.prevent="saveOdometer"><button type="button" class="accordion-trigger" :aria-expanded="expandedForm==='odometer'" @click="toggleForm('odometer')"><span>Odometer</span><span>{{expandedForm==='odometer'?'−':'+'}}</span></button><div v-if="expandedForm==='odometer'" class="accordion-content"><small>Authoritative reading: {{effectiveOdometer??'unavailable'}}</small><label>Current reading<input v-model="odometerReading" inputmode="numeric" type="number" min="0" step="1" required autocomplete="off" :aria-invalid="odometerRegression" /></label><p v-if="odometerWarning" class="field-warning" role="alert">{{odometerWarning}}</p><button type="submit" :disabled="odometerSubmitDisabled">Record Odometer</button></div></form><form v-if="revenueEnabled" class="accordion" novalidate @submit.prevent="saveRevenue"><button type="button" class="accordion-trigger" :aria-expanded="expandedForm==='revenue'" @click="toggleForm('revenue')"><span>Revenue</span><span>{{expandedForm==='revenue'?'−':'+'}}</span></button><div v-if="expandedForm==='revenue'" class="accordion-content"><label>Amount (₹)<input v-model="revenue" inputmode="decimal" type="number" min="0.01" step="0.01" required autocomplete="off" /></label><button type="submit" :disabled="busy">Record Revenue</button></div></form><form class="accordion" novalidate @submit.prevent="saveFuel"><button type="button" class="accordion-trigger" :aria-expanded="expandedForm==='fuel'" @click="toggleForm('fuel')"><span>Fuel</span><span>{{expandedForm==='fuel'?'−':'+'}}</span></button><div v-if="expandedForm==='fuel'" class="accordion-content"><label>Amount (₹)<input v-model="fuelAmount" inputmode="decimal" type="number" min="0.01" step="0.01" required autocomplete="off" /></label><label>Price / kg (₹)<input v-model="fuelPrice" inputmode="decimal" type="number" min="0.01" step="0.01" required autocomplete="off" /></label><small>Odometer: {{effectiveOdometer??'unavailable'}}</small><button type="submit" :disabled="busy">Record Fuel</button></div></form><form class="accordion" novalidate @submit.prevent="saveExpense"><button type="button" class="accordion-trigger" :aria-expanded="expandedForm==='expense'" @click="toggleForm('expense')"><span>Business Expense</span><span>{{expandedForm==='expense'?'−':'+'}}</span></button><div v-if="expandedForm==='expense'" class="accordion-content"><label>Category<input v-model="expenseCategory" required autocomplete="off" /></label><label>Amount (₹)<input v-model="expenseAmount" inputmode="decimal" type="number" min="0.01" step="0.01" required autocomplete="off" /></label><label>Description<input v-model="expenseDescription" autocomplete="off" /></label><button type="submit" :disabled="busy">Record Expense</button></div></form><form class="accordion" novalidate @submit.prevent="saveMaintenance"><button type="button" class="accordion-trigger" :aria-expanded="expandedForm==='maintenance'" @click="toggleForm('maintenance')"><span>Maintenance</span><span>{{expandedForm==='maintenance'?'−':'+'}}</span></button><div v-if="expandedForm==='maintenance'" class="accordion-content"><label>Category<input v-model="maintenanceCategory" required autocomplete="off" /></label><label>Amount (₹)<input v-model="maintenanceAmount" inputmode="decimal" type="number" min="0.01" step="0.01" required autocomplete="off" /></label><label>Odometer<input v-model="maintenanceOdometer" inputmode="numeric" type="number" min="0" step="1" :placeholder="effectiveOdometer==null?'':String(effectiveOdometer)" autocomplete="off" /></label><label>Expected KM life (optional)<input v-model="maintenanceLife" inputmode="numeric" type="number" min="1" step="1" autocomplete="off" /></label><label>Receipt / Reference (optional)<input v-model="maintenanceReference" autocomplete="off" /></label><label>Description<input v-model="maintenanceDescription" autocomplete="off" /></label><button type="submit" :disabled="busy">Record Maintenance</button></div></form></div></template><template v-else-if="section==='summary'"><div class="summary-grid"><article><span>Business KM</span><strong>{{number(report.businessDistanceKm)}} km</strong></article><article><span>Personal KM</span><strong>{{number(report.personalDistanceKm)}} km</strong></article><article><span>Revenue</span><strong>{{money(report.revenuePaise)}}</strong></article><article><span>Fuel</span><strong>{{money(report.fuelPaise)}}</strong></article><article><span>Maintenance</span><strong>{{money(report.maintenancePaise)}}</strong></article><article><span>Expenses</span><strong>{{money(report.expensePaise)}}</strong></article><article><span>Loan Payments</span><strong>{{money(report.loanPaise)}}</strong></article><article><span>Fixed Overhead</span><strong>{{money(report.fixedOverheadPaise)}}</strong></article><article class="wide"><span>Total Operating Cost</span><strong>{{money(report.totalExpensePaise)}}</strong></article></div><p class="context">Personal-use KM remains separated from business accounting. Maintenance is usage-allocated when an expected KM life is configured.</p></template><template v-else><div v-if="!history.length" class="empty">No operational history is available yet.</div><div v-else class="history-list"><article v-for="item in history" :key="item.date"><strong>{{item.date}}</strong><span>{{number(item.businessKm)}} km</span><span>{{money(item.revenuePaise)}}</span></article></div></template></section></template>
<style scoped>.work-operations{display:grid;gap:12px;padding:14px;border:1px solid var(--kfe-ui-border);border-radius:20px;background:var(--kfe-ui-surface);box-shadow:var(--kfe-ui-shadow)}.operations-header{display:flex;justify-content:space-between;gap:10px;align-items:center}.eyebrow{font-size:.65rem;font-weight:900;color:var(--kfe-muted-text)}h2{margin:2px 0 0;font-size:1.1rem}.state{font-size:.7rem;color:var(--kfe-muted-text)}.tabs{display:grid;grid-template-columns:repeat(3,1fr);gap:4px;padding:4px;border:1px solid var(--kfe-ui-border);border-radius:12px;background:var(--kfe-ui-surface-2)}.tabs button{border:0;border-radius:9px;padding:9px;font-weight:800;background:transparent;color:var(--kfe-muted-text);min-height:48px;min-width:48px}.tabs button.active{background:var(--kfe-accent-soft);color:var(--kfe-accent)}.forms{display:grid;gap:8px}.accordion{display:grid;gap:0;border:1px solid var(--kfe-ui-border);border-radius:15px;background:var(--kfe-ui-surface-2);overflow:hidden}.accordion-trigger{display:flex;align-items:center;justify-content:space-between;width:100%;min-height:48px;padding:11px 12px;border:0;background:transparent;color:var(--kfe-ui-text);font-weight:850;text-align:left}.accordion-trigger span:last-child{font-size:1.15rem;color:var(--kfe-muted-text)}.accordion-content{display:grid;gap:7px;padding:0 12px 12px}.accordion-content button{min-height:48px;min-width:48px;border:0;border-radius:9px;background:var(--kfe-accent);color:#fff;font-weight:850}.accordion-content button:disabled{opacity:.55}h3{margin:0;font-size:.9rem}label{display:grid;gap:4px;font-size:.7rem;font-weight:800;color:var(--kfe-muted-text)}input{width:100%;box-sizing:border-box;min-height:40px;border:1px solid var(--kfe-ui-border);border-radius:9px;padding:8px;background:var(--kfe-ui-surface);color:var(--kfe-ui-text)}.field-warning{margin:0;padding:7px 8px;border:1px solid var(--kfe-danger,#d92d20);border-radius:8px;background:var(--kfe-ui-surface);color:var(--kfe-danger,#d92d20);font-size:.72rem;font-weight:700;line-height:1.35}.accordion-content input[aria-invalid="true"]{border-color:var(--kfe-danger,#d92d20);outline:2px solid color-mix(in srgb,var(--kfe-danger,#d92d20) 18%,transparent)}small,.context,.empty{font-size:.7rem;color:var(--kfe-muted-text);line-height:1.4}.notice{margin:0;padding:9px 10px;border-radius:10px;font-size:.72rem}.success{background:var(--kfe-accent-soft);color:var(--kfe-accent)}.error{background:var(--kfe-ui-surface-2);color:var(--kfe-ui-text);border:1px solid var(--kfe-ui-border)}.summary-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.summary-grid article{display:grid;gap:4px;padding:11px;border:1px solid var(--kfe-ui-border);border-radius:12px}.summary-grid span{font-size:.67rem;color:var(--kfe-muted-text)}.summary-grid strong{font-size:.95rem}.summary-grid .wide{grid-column:1/-1;border-color:var(--kfe-accent)}.history-list{display:grid;gap:7px}.history-list article{display:grid;grid-template-columns:1fr auto auto;gap:10px;align-items:center;padding:10px;border:1px solid var(--kfe-ui-border);border-radius:11px}.history-list span{font-size:.72rem;color:var(--kfe-muted-text)}@media(max-width:600px){.forms{grid-template-columns:1fr}}@media(max-width:360px){.summary-grid{grid-template-columns:1fr}.summary-grid .wide{grid-column:auto}}</style>
